# Copy the log files generated by "HLP_004_Generate_LSPC_Workflow_Bat.R" 
# into the model hydrology archive folder


#### Setup ####

# Clear the environment
base::remove(list = ls())


# Import packages
source("Additional_Scripts/Load_Packages.R")


# Import shared functions
source("Shared_Scripts/!Shared_Functions_Importer.R")


#### Functions ####

mainProcedure <- function () {
  
  cat("\n\n")
  cat("Starting 'HLP_005_Archive_Log_Files.R'!\n")
  
  
  # Import a function from another script
  functionStealer("W3_LSPC_Watershed/scripts/LSPC_012_Archive_Raw_and_Staged_Files.R",
                  "get_lspc_archive_folder")
  
  
  # Import the start and end date
  source("W2_Russian_River/Scripts/HLP_002_Validate_and_Import_Data_Scraping_Bounds.R")
  
  
  # Get the location of the archive folder
  dirPath <- get_lspc_archive_folder(startDate, endDate)
  
  
  cat("\n[1/1]\tCopying log files...\n")
  
  
  # Get a list of log files in the "Workflow_Bin" folder
  logFiles <- list.files("W3_LSPC_Watershed/Workflow_Bin/", pattern = "\\.log$",
                         full.names = TRUE) |>
    normalizePath(mustWork = FALSE)
  
  
  # Copy these files to the archive folder if they were recently generated
  if (length(logFiles) > 0) {
    
    for (i in 1:length(logFiles)) {
      
      # If a file was generated more than two hours ago, don't copy the file
      if (difftime(Sys.time(), file.info(logFiles)[["mtime"]], units = "mins") > 120) {
        
        next
        
      }
      
      
      # Otherwise, copy the file to the archive folder
      copyFile(from = logFiles[i] |> 
                 normalizePath(mustWork = FALSE),
               to = paste0(dirPath, "/", logFiles[i] |> extract_filename()) |> 
                 normalizePath(mustWork = FALSE))
      
    }
    
  }
  
  
  cat("\tDone!\n\n")
  
  
  cat(col_green("\n'HLP_005_Archive_Log_Files.R' is complete!\n\n"))
  
  
  # Return nothing
  return(invisible(NULL))
  
}



#### Script Execution ####

mainProcedure()


# Clean up
base::remove(list = ls())
